(() => {
  const q = window.__qc = {
    origin: location.origin, realFetch: window.fetch.bind(window), permits: [], events: [],
    owned: new Set(), synthetic: new Set(), runs: new Set(), ids: {}, gates: new Map(),
    violations: [], jsErrors: [], failures: [], shown: [], finishes: [], opens: new Map(),
    holdStatus: false, statusWaiters: [], accepted: [], readonlyPosts: [],
    holdHistory: false, historyHeld: false, historyWaiting: 0, historyGateWait: null,
    historyGateRelease: null, historyActualHasRecover: false, historySnapshots: 0, freshHistoryAfterGate: 0,
    holdFreshHistory: false, freshHistoryWait: null, freshHistoryRelease: null, freshHistoryWaiting: 0,
  };
  q.assert = (condition, message) => { if (!condition) throw Error(message); };
  q.until = async (fn, milliseconds = 45000) => {
    const end = Date.now() + milliseconds;
    while (Date.now() < end) {
      if (fn()) return true;
      await new Promise(resolve => setTimeout(resolve, 40));
    }
    return false;
  };
  q.read = async path => {
    const url = new URL(path, location.href);
    q.assert(url.origin === q.origin, 'read left the owned origin');
    const response = await q.realFetch(url.href);
    q.assert(response.ok, 'owned read refused: ' + url.pathname + ' ' + response.status);
    return response.json();
  };
  q.terminal = async id => {
    q.assert(q.owned.has(id), 'terminal lookup is not an owned real job');
    const end = Date.now() + 45000;
    while (Date.now() < end) {
      const job = await q.read('/api/jobs/' + id);
      if (['done', 'error', 'cancelled'].includes(job.status)) return job;
      await new Promise(resolve => setTimeout(resolve, 40));
    }
    throw Error('owned job did not settle: ' + id);
  };
  q.row = id => els.queueList.querySelector('li[data-id="' + id + '"] [data-queue-action="cancel"]');
  q.front = id => [...els.queueList.children].find(row => row.dataset.id === id)?.querySelector('[data-queue-action=front]');
  q.wires = id => q.events.filter(event => event.path === '/api/jobs/' + id + '/cancel').length;
  q.safe = () => location.origin === q.origin && q.violations.length === 0
    && q.jsErrors.length === 0 && q.failures.length === 0 && q.permits.length === 0;
  q.allow = (path, { tag = path, mode = 'pass', body = null, detail = 'Controlled queued cancellation failure' } = {}) => {
    const url = new URL(path, location.href);
    q.assert(url.origin === q.origin, 'permit left the owned origin');
    const ownedAction = /^\/api\/jobs\/([^/]+)\/(cancel|pause|front)$/.exec(url.pathname);
    q.assert(url.pathname === '/api/generate' || url.pathname === '/api/fake/step'
      || (ownedAction && (q.owned.has(ownedAction[1]) || q.synthetic.has(ownedAction[1]))),
      'permit targets an unowned mutation: ' + path);
    q.assert(!q.gates.has(tag), 'permit tag reused: ' + tag);
    const grant = { path: url.pathname + url.search, tag, mode, detail, body: body === null ? null : JSON.stringify(body),
      seen: false, responseReady: false, released: !mode.startsWith('hold-') };
    if (!grant.released) grant.wait = new Promise(resolve => { grant.release = resolve; });
    q.gates.set(tag, grant);
    q.permits.push(grant);
    return grant;
  };
  q.release = tag => {
    const gate = q.gates.get(tag);
    q.assert(gate && gate.seen && !gate.released, 'no pending owned gate: ' + tag);
    gate.released = true;
    gate.release();
  };
  q.releaseHistory = () => {
    q.assert(q.holdHistory && q.historyHeld && q.historyGateRelease, "no held controlled history snapshot");
    q.holdHistory = false;
    const release = q.historyGateRelease;
    q.historyGateRelease = null;
    release();
  };
  q.releaseFreshHistory = () => {
    q.assert(q.holdFreshHistory && q.freshHistoryRelease, "no held fresh history gate");
    q.holdFreshHistory = false;
    const release = q.freshHistoryRelease;
    q.freshHistoryRelease = null;
    release();
  };
  q.releaseStatus = () => {
    q.holdStatus = false;
    const waiting = q.statusWaiters.splice(0);
    waiting.forEach(resolve => resolve());
  };
  window.addEventListener('error', event => q.jsErrors.push(String(event.message || 'window error')));
  window.addEventListener('unhandledrejection', event => q.jsErrors.push(String(event.reason)));
  const realShowError = showError;
  showError = (...args) => { q.shown.push(String(args[0] ?? '')); return realShowError(...args); };
  const realFinish = finishJob;
  finishJob = (id, data, options) => {
    q.finishes.push({ id, status: data.status, count: data.image_count, error: data.error,
      submitted: !!options?.submitted, foreign: !!options?.foreign });
    return realFinish(id, data, options);
  };
  const RealEventSource = window.EventSource;
  window.EventSource = class extends RealEventSource {
    constructor(url, options) {
      const address = new URL(url, location.href);
      const match = /^\/api\/jobs\/([^/]+)\/stream$/.exec(address.pathname);
      if (address.origin !== q.origin || !match || !q.owned.has(match[1])) {
        q.violations.push('unowned event stream: ' + address.pathname);
        throw Error('event stream is not an owned fake job');
      }
      q.opens.set(match[1], (q.opens.get(match[1]) || 0) + 1);
      super(url, options);
    }
  };
  window.fetch = async (input, options) => {
    const address = new URL(typeof input === 'string' || input instanceof URL ? input : input.url, location.href);
    const method = String(options?.method || (input instanceof Request ? input.method : 'GET')).toUpperCase();
    if (address.origin !== q.origin) {
      q.violations.push(method + ' off-origin ' + address.href);
      throw Error('fixture refused an off-origin request');
    }
    const path = address.pathname + address.search;
    if (method === 'GET' || method === 'HEAD') {
      const response = await q.realFetch(input, options);
      if (method === 'GET' && path === '/api/jobs?include_finished=true' && q.holdHistory) {
        const listed = await response.clone().json();
        q.assert(response.ok && Array.isArray(listed), 'controlled history source did not answer');
        q.historyActualHasRecover ||= listed.some(job => job.job_id === q.ids.recover);
        q.historyHeld = true;
        q.historySnapshots++;
        q.historyWaiting++;
        try { await q.historyGateWait; } finally { q.historyWaiting--; }
        return response;
      }
      if (method === 'GET' && path === '/api/jobs?include_finished=true' && q.historyHeld) {
        q.freshHistoryAfterGate++;
        if (q.holdFreshHistory) {
          q.freshHistoryWaiting++;
          try { await q.freshHistoryWait; } finally { q.freshHistoryWaiting--; }
        }
      }
      if (method === 'GET' && address.pathname === '/api/status' && q.holdStatus) {
        await new Promise(resolve => q.statusWaiters.push(resolve));
      }
      return response;
    }
    const finish = /^\/api\/runs\/([^/]+)\/finish\/preview$/.exec(address.pathname);
    if (method === 'POST' && !address.search && (
      ['/api/grid/preview', '/api/prompt/analyze'].includes(address.pathname)
      || (finish && q.runs.has(decodeURIComponent(finish[1])))
    )) {
      q.readonlyPosts.push(address.pathname);
      return q.realFetch(input, options);
    }
    const body = options?.body ?? null;
    const at = q.permits.findIndex(grant => grant.path === path
      && grant.body === (body === null || body === undefined || body === '' ? null : String(body)));
    if (method !== 'POST' || at < 0) {
      q.violations.push(method + ' ' + path);
      throw Error('fixture refused an unapproved mutation: ' + method + ' ' + path);
    }
    const grant = q.permits.splice(at, 1)[0];
    grant.seen = true;
    const event = { path, tag: grant.tag, mode: grant.mode, forwarded: false };
    q.events.push(event);
    const mode = grant.mode.replace(/^hold-/, '');
    let response;
    if (mode === 'pass') {
      event.forwarded = true;
      response = await q.realFetch(input, options);
      if (/^\/api\/jobs\/[^/]+\/front$/.test(address.pathname) && response.ok) {
        grant.frontIds = (await response.clone().json()).active_jobs;
      }
      if (address.pathname === '/api/generate' && response.ok) {
        const accepted = await response.clone().json();
        q.assert(typeof accepted.job_id === 'string' && /^[a-f0-9]{12}$/.test(accepted.job_id), 'no real fake job receipt');
        q.assert(!q.owned.has(accepted.job_id) && !(accepted.more?.length), 'duplicate or split fake submission');
        q.owned.add(accepted.job_id);
        q.accepted.push(accepted.job_id);
        q.assert(typeof grant.submitLabel === 'string' && grant.tag === 'submit-' + grant.submitLabel,
          'accepted submission has no exact fixture label');
        grant.acceptedId = accepted.job_id;
        q.ids[grant.submitLabel] = accepted.job_id;
        if (typeof accepted.run_id === 'string') q.runs.add(accepted.run_id);
      }
    } else if (mode === 'http500') {
      response = new Response(JSON.stringify({ detail: grant.detail }),
        { status: 500, headers: { 'Content-Type': 'application/json' } });
    } else if (mode === 'badjson') {
      response = new Response('{', { status: 200, headers: { 'Content-Type': 'application/json' } });
    } else if (mode !== 'offline') {
      throw Error('unknown fixture response mode');
    }
    grant.responseStatus = response?.status ?? null;
    grant.responseReady = true;
    if (!grant.released) await grant.wait;
    if (mode === 'offline') throw new TypeError('Controlled queued cancellation transport loss');
    return response;
  };
  q.submit = async (label, seed, { holder = false, fail = false } = {}) => {
    const payload = { prompt: 'queue cancellation smoke ' + label + (fail ? ' [fail]' : ''),
      width: 256, height: 256, steps: holder ? 12 : 1, seed, ...(holder ? { runs: 2 } : {}) };
    const grant = q.allow('/api/generate', { tag: 'submit-' + label, body: payload });
    grant.submitLabel = label;
    const shownAt = q.shown.length, failuresAt = q.failures.length;
    let refused = '', completed = false;
    void startJob('/api/generate', payload, {
      onRefused: error => { refused = String(error?.message ?? error); },
    }).catch(error => { refused = String(error); q.failures.push(refused); })
      .finally(() => { completed = true; });
    const diagnostic = () => JSON.stringify({ label, seen: grant.seen,
      status: grant.responseStatus ?? null, accepted: grant.acceptedId ?? null,
      submitting, retained: !!grant.acceptedId && submissions.has(grant.acceptedId),
      modelState, serverOffline, busy, refused,
      shown: q.shown.slice(shownAt).filter(Boolean).slice(-2) });
    q.assert(await q.until(() => {
      const error = refused || q.failures.slice(failuresAt).join('; ');
      q.assert(!error, 'submission refused: ' + diagnostic());
      q.assert(!(grant.responseReady && grant.responseStatus >= 400), 'submission HTTP refusal: ' + diagnostic());
      if (grant.acceptedId && !submitting && submissions.has(grant.acceptedId)) return true;
      q.assert(!(completed || (!grant.acceptedId && q.shown.slice(shownAt).some(Boolean))),
        'submission did not retain an accepted receipt: ' + diagnostic());
      return false;
    }), 'submission acceptance timed out: ' + diagnostic());
    q.assert(q.owned.has(q.ids[label]) && submissions.has(q.ids[label]), 'accepted receipt missing: ' + label);
    return q.ids[label];
  };
  q.pause = async (id, value) => {
    q.assert(currentJob === id && busy, 'pause targets another watched job');
    q.assert(els.pause.textContent === (value ? 'Pause' : 'Resume'), 'pause label does not match the intended request');
    q.allow('/api/jobs/' + id + '/pause?value=' + value, { tag: 'pause-' + id + '-' + value });
    els.pause.click();
    q.assert(await q.until(() => value ? skipSnapshot?.paused && els.pause.textContent === 'Resume'
      : !skipSnapshot?.paused), 'owned pause did not acknowledge');
  };
  q.step = async seconds => {
    const body = { seconds };
    q.allow('/api/fake/step', { tag: 'step-' + seconds, body });
    await api('/api/fake/step', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
  };
  return true;
})()
